ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    "GetBillsOutput": {
        "WSResponseHeader2" :
        {
            "System":{
				"name": vars.attributes.name,
				"correlationID": correlationId,
				"processingServer": vars.attributes.processingServer
            },
            "Service":{
                "status" : payload.Result.status
            }
        },
        "Bills" : payload.Bills,
        "Result" : payload.Result-"status"
    }
}

%dw 2.0
output application/json
---
{
    "GetBillsOutput": {
        "WSResponseHeader2" :
        {
            "System":{
				"name": vars.attributes.name,
				"correlationID": correlationId,
				"processingServer": vars.attributes.processingServer
            },
            "Service":{
                "status" : payload.Result.status,
                "statusDetail": {
                    "errorCode" : payload.Result.code,
                    "errorMessage" : payload.Result.description
                }
            }
        },
        "Result" : payload.Result-"status"
    }
}
